sp_widget.client_script:
api.controller = function($scope) {

  // $sp.getParameter doesn't resolve for theme-level widgets,
  // so read the page id straight from the URL.
  var m = window.location.search.match(/[?&]id=([^&]+)/);
  $scope.pageId = m ? m[1] : 'wrm_landing';

  // Dark mode only applies to our own pages. Catalog pages use
  // stock Bootstrap styling that doesn't read our variables, so
  // it would render half-dark and unreadable.
  var OURS = ['wrm_landing', 'wrm_spaces', 'wrm_reservations', 'wrm_help'];
  var supported = OURS.indexOf($scope.pageId) > -1;

  var KEY = 'wrm-dark';

  function apply(on) {
    if (on && supported) {
      document.body.classList.add('dark');
    } else {
      document.body.classList.remove('dark');
    }
  }

  $scope.dark = localStorage.getItem(KEY) === '1';
  $scope.darkAvailable = supported;
  apply($scope.dark);

  $scope.toggleDark = function() {
    $scope.dark = !$scope.dark;
    localStorage.setItem(KEY, $scope.dark ? '1' : '0');
    apply($scope.dark);
  };
};

sp_widget.css:
.wrm-hd {
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}
.wrm-hd-inner {
  max-width: 1400px; margin: 0 auto;
  padding: 13px 20px;
  display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
}

.wrm-hd-brand { display: flex; align-items: center; gap: 9px; text-decoration: none; }
.wrm-hd-brand:hover { text-decoration: none; }
.wrm-hd-brand .mark {
  width: 20px; height: 20px; background: var(--clay);
  border-radius: var(--r-pill); flex: none;
}
.wrm-hd-brand .word { font-size: 15px; font-weight: 500; color: var(--ink); }

.wrm-hd-live {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 12px; padding: 5px 13px;
  background: var(--free-bg); color: var(--free-fg);
  border-radius: var(--r-pill);
}
.wrm-hd-live .dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: currentColor; flex: none;
}
.wrm-hd-live.low { background: var(--out-bg); color: var(--out-fg); }

.wrm-hd-nav { display: flex; gap: 20px; margin-left: auto; }
.wrm-hd-nav a {
  font-size: 13px; color: var(--ink-2); text-decoration: none;
  padding-bottom: 2px; border-bottom: 2px solid transparent;
}
.wrm-hd-nav a:hover {
  color: var(--ink); text-decoration: none; border-bottom-color: var(--clay);
}
.wrm-hd-nav a.on {
  color: var(--ink);
  border-bottom-color: var(--clay);
}

.wrm-hd-mode {
  background: transparent; border: 1px solid var(--line);
  color: var(--ink-2); width: 30px; height: 30px;
  border-radius: var(--r-pill); cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  font-size: 13px; flex: none;
}
.wrm-hd-mode:hover { color: var(--clay); border-color: var(--clay); }

.wrm-hd-user { display: flex; align-items: center; gap: 11px; }
.wrm-hd-user .mine { font-size: 12px; color: var(--ink-3); }
.wrm-hd-user .av {
  width: 28px; height: 28px; border-radius: var(--r-pill);
  background: var(--surface-2); color: var(--ink-2);
  font-size: 11px; display: flex; align-items: center; justify-content: center;
  flex: none;
}

@media (max-width: 640px) {
  .wrm-hd-nav { margin-left: 0; width: 100%; order: 3; }
}

sp_widget.script:
(function() {
  var u = gs.getUser();
  var name = u.getFirstName() || u.getName();
  data.userName = name;

  // Initials for the avatar circle.
  var f = (u.getFirstName() || '').charAt(0);
  var l = (u.getLastName()  || '').charAt(0);
  data.initials = (f + l).toUpperCase() || name.charAt(0).toUpperCase();

  // Live availability, carried in the chrome on every page.
  // One count, so it's cheap enough to run on every request.
  var free = new GlideRecord('x_1903615_worksp_0_workspace_options');
  free.addQuery('status', 'available');
  free.query();
  data.free = free.getRowCount();

  // This user's live reservations, so the nav can badge them.
  var mine = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  mine.addQuery('reserved_for', gs.getUserID());
  mine.addQuery('reservation_status', 'IN', 'pending_check_in,checked_in');
  mine.query();
  data.mine = mine.getRowCount();
})();
